{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — A gentle sound gathering</title>
  <meta name="description" content="A warm, story-driven guide to restorative sound gatherings and personal sessions in {{CITY}}, {{STATE}}." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <svg class="logo" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="44" stroke-width="2" fill="none" stroke="#5b4b8a"/></svg>
      <div>
        <strong class="name">{{BUSINESS_NAME}}</strong>
        <div class="tag">{{TAGLINE}}</div>
      </div>
    </div>

    <nav class="main-nav">
      <a href="index.html">Gatherings</a>
      <a href="events.html">Schedule</a>
      <a href="private-sessions.html">Private Work</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Our Story</a>
      <a href="faq.html">Notes & Safety</a>
      <a href="book.html" class="primary">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero">
      <svg class="pattern" role="img" aria-hidden="true"><use href="assets/img/pattern.svg#p" /></svg>
      <div class="hero-inner">
        <h1>Slow down into sound — a warm assembly for presence and quiet turning.</h1>
        <p class="lead">Join intimate gatherings or private sessions where tuned resonances help you land, write an intention, and leave steadier than you arrived.</p>
        <div class="hero-ctas">
          <a class="btn btn-primary" href="#book">{{PRIMARY_CTA_LABEL}}</a>
          <button class="btn" id="tryNowBtn">Try a short practice</button>
        </div>
        <div class="hero-note">Next session preview — limited seats. Phone: {{PHONE}}</div>
      </div>

      <aside class="next-event" id="nextEvent">
        <h3>Upcoming session</h3>
        <div class="event-card">
          <div class="event-meta" id="nextEventDate">—</div>
          <div class="event-title">Evening Field: 60-min communal session</div>
          <div class="event-actions">
            <label>Choose seats:
              <select id="seatSelect"></select>
            </label>
            <button id="reserveBtn" class="btn btn-primary">Reserve seats</button>
            <button id="packBtn" class="btn">What to bring</button>
          </div>
          <div class="event-availability" id="availability">Availability: —</div>
        </div>
      </aside>
    </section>

    <!-- Story -->
    <section class="story">
      <div class="col">
        <h2>Stories beneath the sound</h2>
        <p>We think of a session as a short story: arriving, a move inward, and a gentle return. Each meeting combines tuned bowls, guided intention, and space for private reflection. The frame is simple: small group, soft lighting, and a steady arc of sound that invites noticing.</p>
        <p class="small">Contraindications: If you are pregnant, have uncontrolled epilepsy, pacemaker or other implanted medical device, or are currently under strong psychiatric medication changes, consult your clinician before attending. If you have specific concerns, contact us at {{EMAIL}}.</p>
      </div>
      <div class="col">
        <h3>How we gather</h3>
        <ul>
          <li>Brief welcome + intention setting</li>
          <li>Layered resonant instruments (bowls, chimes, gentle drums)</li>
          <li>Silent return with journaling prompts</li>
        </ul>
      </div>
    </section>

    <!-- Framework -->
    <section class="framework">
      <h2>Our session structure</h2>
      <div class="cards">
        <div class="card">
          <h4>Ground (10–15 min)</h4>
          <p>Settling into breath and noticing the body as a home for sound.</p>
        </div>
        <div class="card">
          <h4>Field (30–40 min)</h4>
          <p>Longer resonant passages create a surface for attention to rest.</p>
        </div>
        <div class="card">
          <h4>Return (10–15 min)</h4>
          <p>A short journaling prompt and shared close to bring insights into daily life.</p>
        </div>
      </div>
    </section>

    <!-- Offers -->
    <section class="offers" id="book">
      <h2>Offerings</h2>
      <div class="offer-grid">
        <article class="offer">
          <h3>Communal Field</h3>
          <p>60-minute group gatherings, comfortable mats and cushions provided. Bring a small journal if you like.</p>
          <div class="price">$28 / person</div>
          <a href="events.html" class="btn">See dates</a>
        </article>
        <article class="offer">
          <h3>Private Session</h3>
          <p>One-on-one sound guidance tailored to intention-setting and integration.</p>
          <div class="price">From $120</div>
          <a href="private-sessions.html" class="btn">Learn more</a>
        </article>
        <article class="offer">
          <h3>Mini Series: Anchor Trio</h3>
          <p>A three-session bundle for beginning a weekly practice.</p>
          <div class="price">$75 / series</div>
          <a href="pricing.html" class="btn">Reserve a series</a>
        </article>
      </div>

      <div class="disclaimer small">Please note: sound can be intense for some. If you experience dizziness, strong panic, or physical discomfort, please notify a facilitator immediately and step outside for fresh air. Contraindications apply — see Notes & Safety.</div>
    </section>

    <!-- Pricing (condensed) -->
    <section class="pricing">
      <h2>Simple pricing</h2>
      <ul>
        <li>Drop-in: $28</li>
        <li>Private: $120 / 60 min</li>
        <li>Series: $75 (3 sessions)</li>
      </ul>
      <a href="pricing.html" class="btn">Full rates & policies</a>
    </section>

    <!-- Testimonials -->
    <section class="testimonials">
      <h2>Voices</h2>
      <blockquote>
        "I came with a frantic mind and left with a small map. The sound helped me find my feet again." — A.
      </blockquote>
      <blockquote>
        "The private session helped me prepare for a life change with a clearer head." — M.
      </blockquote>
    </section>

    <!-- CTA -->
    <section class="cta">
      <h2>Ready to come in?</h2>
      <p>Book a seat, arrange a private time, or try a short guided moment right now.</p>
      <div class="cta-actions">
        <a href="book.html" class="btn btn-primary">Secure a seat</a>
        <button class="btn" id="tryNowBtn2">Try a short practice</button>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="footer-inner">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <div>{{CITY}}, {{STATE}}</div>
      </div>
      <div>
        <div>Phone: {{PHONE}}</div>
        <div>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
    </div>
    <small class="credits">Small gatherings. Gentle seating. Thoughtful listening.</small>
  </footer>

  <!-- Guided modal -->
  <div id="guidedModal" class="modal" aria-hidden="true">
    <div class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
      <button class="modal-close" id="modalClose">×</button>
      <h3 id="modalTitle">Try a short guided practice</h3>
      <div class="modal-body">
        <div id="stage">
          <div id="breathStage" class="stage-part">
            <h4>Breathing — follow the circle</h4>
            <div class="breath-visual" id="breathVisual" aria-hidden="true"></div>
            <div class="timer" id="breathTimer">00</div>
          </div>
          <div id="journalStage" class="stage-part hidden">
            <h4>Journal prompt</h4>
            <p id="journalPrompt">Where in your life would you like a small easing today?</p>
            <textarea id="journalInput" rows="4" placeholder="A sentence or two..."></textarea>
            <button id="saveJournal" class="btn btn-primary">Save note</button>
          </div>
          <div id="intentStage" class="stage-part hidden">
            <h4>Set an intention</h4>
            <p>Write a short intention to carry with you.</p>
            <input id="intentInput" placeholder="I will..." />
            <button id="finishIntent" class="btn btn-primary">Finish</button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
